"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[1225],{55302(e,n,t){t.r(n),t.d(n,{assets:()=>h,contentTitle:()=>s,default:()=>c,frontMatter:()=>i,metadata:()=>r,toc:()=>d});var o=t(74848),a=t(28453);const i={title:"No One Comes Forward, and It Isn't for Lack of a Case \u2014 In an Unfair Place, Don't Get Entangled; Find the Next Way Out",sidebar_label:"Side article: No One Comes Forward",slug:"/chaos-series/side-no-one-comes-forward",date:new Date("2026-11-23T00:00:00.000Z"),lang:"en",section:"sober-record",topic:"chaos-series",category:"\u6559\u80b2\u8207\u52de\u52d5",article_tags:{zh:["\u8077\u5834\u653f\u6cbb","\u6aa2\u8209","\u533f\u540d","\u51fa\u8def"],en:["workplace-politics","whistleblowing","anonymity","way-out"]},keywords:["reporting system","attribution","anonymity","factions","way out"],summary:"No one comes forward, and not for lack of a case; in an unfair place where you have no voice, don't get entangled; find the next way out.",description:"No one comes forward, and not for lack of a case; in an unfair place where you have no voice, don't get entangled; find the next way out.",status:"published",reading_time:12,series:{order:5}},s="No One Comes Forward, and It Isn't for Lack of a Case \u2014 In an Unfair Place, Don't Get Entangled; Find the Next Way Out",r={id:"series/chaos-series/side-no-one-comes-forward",title:"No One Comes Forward, and It Isn't for Lack of a Case \u2014 In an Unfair Place, Don't Get Entangled; Find the Next Way Out",description:"No one comes forward, and not for lack of a case; in an unfair place where you have no voice, don't get entangled; find the next way out.",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/series/chaos-series/05-side-no-one-comes-forward.md",sourceDirName:"series/chaos-series",slug:"/chaos-series/side-no-one-comes-forward",permalink:"/en/docs/chaos-series/side-no-one-comes-forward",draft:!1,unlisted:!1,tags:[],version:"current",sidebarPosition:5,frontMatter:{title:"No One Comes Forward, and It Isn't for Lack of a Case \u2014 In an Unfair Place, Don't Get Entangled; Find the Next Way Out",sidebar_label:"Side article: No One Comes Forward",slug:"/chaos-series/side-no-one-comes-forward",date:"2026-11-23T00:00:00.000Z",lang:"en",section:"sober-record",topic:"chaos-series",category:"\u6559\u80b2\u8207\u52de\u52d5",article_tags:{zh:["\u8077\u5834\u653f\u6cbb","\u6aa2\u8209","\u533f\u540d","\u51fa\u8def"],en:["workplace-politics","whistleblowing","anonymity","way-out"]},keywords:["reporting system","attribution","anonymity","factions","way out"],summary:"No one comes forward, and not for lack of a case; in an unfair place where you have no voice, don't get entangled; find the next way out.",description:"No one comes forward, and not for lack of a case; in an unfair place where you have no voice, don't get entangled; find the next way out.",status:"published",reading_time:12,series:{order:5}},sidebar:"lucidRecord",previous:{title:"4. The Last Field Never Names the Company",permalink:"/en/docs/chaos-series/the-last-field-never-names-the-company"},next:{title:"How a Day-in-the-Life Video Became a Reason for Layoffs: People Without Capital Punishing People Without Capital",permalink:"/en/docs/notes/day-in-the-life-layoffs"}},h={},d=[{value:"I. The statement Ah Ching never sent (fiction)",id:"i-the-statement-ah-ching-never-sent-fiction",level:2},{value:"II. The system forged the knife; one of your own held it",id:"ii-the-system-forged-the-knife-one-of-your-own-held-it",level:2},{value:"III. Reporting systems protect the reporter",id:"iii-reporting-systems-protect-the-reporter",level:2},{value:"IV. Factions don&#39;t care about industry, only conditions",id:"iv-factions-dont-care-about-industry-only-conditions",level:2},{value:"V. Not a lack of evidence: disclosure pays a negative return",id:"v-not-a-lack-of-evidence-disclosure-pays-a-negative-return",level:2},{value:"VI. A world where everyone does the math",id:"vi-a-world-where-everyone-does-the-math",level:2},{value:"VII. Don&#39;t get entangled; find the next way out",id:"vii-dont-get-entangled-find-the-next-way-out",level:2},{value:"Sources",id:"sources",level:2}];function l(e){const n={a:"a",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(n.header,{children:(0,o.jsx)(n.h1,{id:"no-one-comes-forward-and-it-isnt-for-lack-of-a-case--in-an-unfair-place-dont-get-entangled-find-the-next-way-out",children:"No One Comes Forward, and It Isn't for Lack of a Case \u2014 In an Unfair Place, Don't Get Entangled; Find the Next Way Out"})}),"\n",(0,o.jsx)(n.p,{children:"@Mythogen Engine \xb7 Nov 23, 2026"}),"\n",(0,o.jsx)(n.p,{children:(0,o.jsxs)(n.em,{children:['This is a side article to the series "',(0,o.jsx)(n.a,{href:"/en/docs/chaos-series",children:"Where Does the Chaos Go?"}),'". The four main articles follow how chaos travels from promises down to individuals; this one asks what you can choose when you are inside it and have no voice.']})}),"\n",(0,o.jsx)(n.h2,{id:"i-the-statement-ah-ching-never-sent-fiction",children:"I. The statement Ah Ching never sent (fiction)"}),"\n",(0,o.jsx)(n.p,{children:"Ah Ching spent six years at a design firm. Business didn't grow in those years, and the department lost one or two people every year. The manager's two confidants began claiming every piece of work that went out the door as their own. Ah Ching didn't fight it. He thought the work would speak for itself."}),"\n",(0,o.jsx)(n.p,{children:'The year of the restructuring, he was "invited" to leave. He held no grudge. He even thought leaving early wasn\'t so bad: the people who stayed might not fare any better in the next round.'}),"\n",(0,o.jsx)(n.p,{children:"After he left, he started a channel teaching layout design. Three years later it had passed 100,000 subscribers, earned over 200,000 a month, and employed five people: an editor, a subtitler, a customer-service person and two teaching assistants."}),"\n",(0,o.jsx)(n.p,{children:"Then one Monday, the channel received more than a dozen copyright claims in a single day. Videos came down one after another. After the third strike, the whole channel was terminated. From the name the claimant left behind, he recognised who it was: one of those two confidants."}),"\n",(0,o.jsx)(n.p,{children:"He had evidence. Every source file carried a timestamp; every clip was footage he had shot himself. He wrote a long appeal, and a public statement listing, point by point, what had happened at the company."}),"\n",(0,o.jsx)(n.p,{children:'A friend who is a lawyer heard him out and asked only three questions. How long would the case take? If you win, what do you get back? Win or lose, how will people in the industry look at someone who has "sued a former colleague"?'}),"\n",(0,o.jsx)(n.p,{children:"Ah Ching never sent the statement. He paid off his five staff, opened a new channel, and started again from zero subscribers."}),"\n",(0,o.jsx)(n.p,{children:"This story is fiction. But I suspect many people reading this will recognise at least one person in it."}),"\n",(0,o.jsx)(n.h2,{id:"ii-the-system-forged-the-knife-one-of-your-own-held-it",children:"II. The system forged the knife; one of your own held it"}),"\n",(0,o.jsx)(n.p,{children:"A recent episode of the YouTube channel One Light Cinema (\u4e00\u71c8\u5f71\u8a71) features its host, who goes by Yat Dang, describing more than ten years working as a screenwriter in Beijing. What follows is his own account."}),"\n",(0,o.jsx)(n.p,{children:"In 1999, China's then State Administration of Radio, Film and Television issued a notice capping how many people from Hong Kong, Macau and Taiwan could hold key creative roles on a mainland TV drama. Producers, afraid the policy might tighten while a show was in production, rarely used the full quota. When a slot had to be saved, the screenwriter was always the first to give way, because no viewer changes the channel over who wrote the script."}),"\n",(0,o.jsx)(n.p,{children:"Several patterns followed. The approval paperwork often named a mainland writer from the start, so a Hong Kong writer who did the actual work couldn't be credited. The last 20 to 30 percent of the fee was held back until the script was approved, or even until shooting began or wrapped. At payment time, the producer would pull a supplementary agreement out of a drawer: a voluntary waiver of the writing credit. On one side, a cross-border lawsuit; on the other, hundreds of thousands of yuan for most of a year's work. He says nine and a half writers out of ten sign."}),"\n",(0,o.jsx)(n.p,{children:"But he says the notice was not what hurt most. For several dramas in a row, he worked under the same Hong Kong director-producer, a man of about his age whom he considered a friend. Every time, there was a reason he couldn't be credited: the investors had slotted someone in, this one was purely mainland money, next time for sure. Then a veteran producer spelled it out for him. The quota was only an excuse. Once you are credited and your name gets known, you raise your price or go solo. Keep you without a track record, and you stay with him as his cheap labour."}),"\n",(0,o.jsx)(n.p,{children:"Yat Dang's conclusion: the system forged a knife, and the one who picks it up and stabs you is sometimes one of your own, someone who speaks your dialect."}),"\n",(0,o.jsx)(n.p,{children:"This holds well beyond screenwriting. For a screenwriter, the credit is the only bargaining chip. For others, it is a patent, a client list, a portfolio, a channel. These are all visible records. No one needs to prove you wrong. They only need to make those records disappear, and you lose your place at the negotiating table."}),"\n",(0,o.jsx)(n.h2,{id:"iii-reporting-systems-protect-the-reporter",children:"III. Reporting systems protect the reporter"}),"\n",(0,o.jsx)(n.p,{children:"Yat Dang tells another story. The original writer of one drama was a member of the Writers' Association, and many scenes in his script simply couldn't be filmed. Yat Dang was brought in to put out the fire and rewrote it almost from scratch. For once, the producers were willing to put his name in the opening credits. The original writer sued over his right of authorship, and won, because he held a formal contract. The process recognised the paperwork, not the person who wrote the words."}),"\n",(0,o.jsx)(n.p,{children:"Platform reporting systems run on the same logic. Filing a report costs almost nothing; the person reported has to prove their own innocence. The system doesn't first decide whether a report is made in good faith or bad. It acts on the reported content first. The person it protects is the one who pressed the button."}),"\n",(0,o.jsx)(n.p,{children:"A channel earning over 200,000 and supporting a team of five to ten can be shut down by one wave of malicious reports. So people can't help fearing this kind of person. What they fear isn't whether such people are right, but the fact that they exist at all."}),"\n",(0,o.jsx)(n.p,{children:'It happened to me once. I shared my essay "The Efficiency Trap" in a Facebook community of over a million members. One member there, who has published a book, had long ago claimed that "owning 48 skills is like owning 48 employees," and later began running courses charging ten to twenty thousand for a few hours. I wasn\'t targeting him. I only pointed out that if the underlying model doesn\'t change, a skill is just a different set of instructions; it doesn\'t raise intelligence, and even 48 skills hit the same intelligence ceiling.'}),"\n",(0,o.jsx)(n.p,{children:"The post was quickly removed, and I was kicked out of the community. I had to switch to another account just to find the group again. I never said anyone was a fraud. But in that system, none of that mattered."}),"\n",(0,o.jsx)(n.h2,{id:"iv-factions-dont-care-about-industry-only-conditions",children:"IV. Factions don't care about industry, only conditions"}),"\n",(0,o.jsx)(n.p,{children:"One viewer commented that Hong Kong screenwriters have it no differently. Yat Dang replied, in effect, that any industry that depends heavily on introductions and connections is likely to work this way."}),"\n",(0,o.jsx)(n.p,{children:"I agree. This can happen in any industry, provided three conditions hold at once:"}),"\n",(0,o.jsxs)(n.ol,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Resources are allocated through connections."})," Names, deals and positions are decided privately by a few people, with no public record anyone can check against."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"The gatekeepers are of one voice."})," Those holding power share a background, naturally close ranks, and keep outsiders out."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"The pie is shrinking."})," When there isn't enough to go round, taking your share is how they keep theirs."]}),"\n"]}),"\n",(0,o.jsx)(n.p,{children:"\"One of your own\" here doesn't mean someone from your hometown. Yat Dang and that producer were both Hong Kong people who spoke Cantonese, yet Yat Dang was never one of the producer's own; he was the producer's resource. One's own are the people inside the circle who share in the spoils. The system's limits were real, but because the person in power allocated them, he could present his own choices as something the system forced on him."}),"\n",(0,o.jsx)(n.p,{children:"I once worked at the Asia headquarters of a foreign multinational. East Asia was run by Singaporean and Malaysian management, surrounded by many foreigners and returnees from overseas, so no local faction could dominate. The company was also expanding, so people were busy taking new positions instead of grabbing others'. The second and third conditions were broken, so even where factions existed, they didn't dare be so brazen."}),"\n",(0,o.jsx)(n.p,{children:"But this only means factions were harder to form, not that foreign companies have none. Expansion merely creates the conditions for avoiding infighting; in the end it still comes down to people. Mixed management is the same: expatriates can form a circle of their own. Once the pie starts to shrink, the same company can become a different place."}),"\n",(0,o.jsx)(n.h2,{id:"v-not-a-lack-of-evidence-disclosure-pays-a-negative-return",children:"V. Not a lack of evidence: disclosure pays a negative return"}),"\n",(0,o.jsx)(n.p,{children:"No outsider can verify what Yat Dang describes, and neither can I. But life experience tells me that even if it isn't exact in every detail, it is roughly how things go. And the reason such things stay forever at dinner tables and in rumour is not that they never happened."}),"\n",(0,o.jsx)(n.p,{children:"Two situations need to be told apart. Yat Dang signed the paper, trading his credit for the final payment; legally, there is nothing left to contest. The other is having evidence and a case to argue, yet choosing not to fight. What I went through myself was the latter. I never went to court, not because I was in the wrong, but because I had done the math."}),"\n",(0,o.jsxs)(n.p,{children:["I turned that experience into a novel, ",(0,o.jsx)(n.a,{href:"/en/docs/mirror-realm/prologue",children:(0,o.jsx)(n.em,{children:"Mirror Realm"})}),". It is a story about evidence that costs a great deal to bring and returns very little. Interested readers can start with ",(0,o.jsx)(n.a,{href:"/en/docs/mirror-realm/prologue",children:'the prologue, "Ways of Disappearing"'})," (in Chinese)."]}),"\n",(0,o.jsx)(n.p,{children:"The math is simple:"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"The cost of fighting:"})," time, legal fees, and the toll a lawsuit takes on your mind."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"What you get if you win:"})," proof that the company or the team had a problem, or a little compensation. The company stays open; those people keep their jobs."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"The price you pay, win or lose:"}),' a record in the industry as someone who "exposes companies," and every future HR check that turns it up will shut you out. Of those who organise unions or lead strikes, how many come out well?']}),"\n"]}),"\n",(0,o.jsx)(n.p,{children:"Some will say: then do it anonymously. Government campaigns and corporate compliance codes often encourage people to come forward anonymously. But in reality, true anonymity barely exists. What you report gives away who you are, because few people knew about it to begin with. People who come forward anonymously are still found out, and still retaliated against."}),"\n",(0,o.jsx)(n.p,{children:"Anonymity has worked before. But for it to work, the conditions are complex and demanding: whistleblower protections must actually function, those handling reports must be truly independent, and the wider climate and political environment must be able to hold it up. Lose any one of these, and anonymity is just a phrase that makes you feel safe."}),"\n",(0,o.jsx)(n.p,{children:"So silence isn't cowardice; it's rational. The system ensures one thing: even when right is on your side, winning the argument gets you nothing."}),"\n",(0,o.jsx)(n.p,{children:"This is exactly why malicious reporters act with impunity. They've seen through the math. They don't need to be right, because they know you won't hit back: lose and you lose everything, win and you gain nothing. The whole cost of fighting back falls on the victim, while pressing a report button never costs a cent."}),"\n",(0,o.jsx)(n.h2,{id:"vi-a-world-where-everyone-does-the-math",children:"VI. A world where everyone does the math"}),"\n",(0,o.jsxs)(n.p,{children:["Not every setback is predation. Hong Kong comedian Dayo Wong has recalled that when Michael Hui brought him in to co-write the 1992 film ",(0,o.jsx)(n.em,{children:"The Magic Touch"})," (\u795e\u7b97), he wrote the second male lead to be as cool as possible, intending to play the part himself. The role went to Leon Lai instead, and Wong ended up playing a lawyer on the villain's side (",(0,o.jsx)(n.a,{href:"https://www.hk01.com/%E9%9B%BB%E5%BD%B1/977102/%E8%A8%B1%E5%86%A0%E6%96%87%E9%BB%83%E5%AD%90%E8%8F%AF32%E5%B9%B4%E5%BE%8C%E5%86%8D%E5%BA%A6%E5%90%88%E4%BD%9C-%E5%85%A9%E4%BB%A3%E7%AC%91%E5%8C%A0%E5%90%88%E9%AB%94%E8%AA%93%E5%89%B5%E9%81%8E%E5%84%84%E7%A5%A8%E6%88%BF%E7%A5%9E%E8%A9%B1",children:"HK01"}),"). Scripts get rewritten and roles get recast; that is normal in the business, and sometimes it is just bad luck. The difference lies in whether someone deliberately erases your record so that you stay where you are forever."]}),"\n",(0,o.jsx)(n.p,{children:"Back to Ah Ching. He didn't send the statement, not because he was wrong, but because he had done the math. When everyone does this math, only two kinds of people are left speaking: those who pay no price, and those with nothing left to lose."}),"\n",(0,o.jsx)(n.p,{children:"A world where no one dares to speak is not a world without right and wrong. Right and wrong are still there, only kept at dinner tables, in cha chaan teng and in private messages, never becoming a record. And right and wrong without a record will, in the end, lose to lies backed by paperwork."}),"\n",(0,o.jsx)(n.h2,{id:"vii-dont-get-entangled-find-the-next-way-out",children:"VII. Don't get entangled; find the next way out"}),"\n",(0,o.jsx)(n.p,{children:"What this essay wants to say is not, in the end, how to fight back."}),"\n",(0,o.jsx)(n.p,{children:"I'm not trying to judge whether this world has true fairness, or true anonymity. What I want to say is that each person has to think it through carefully for themselves: is the place and position you are in suited to resistance?"}),"\n",(0,o.jsx)(n.p,{children:"My judgement is that almost everywhere, including in the present climate, it is not. In most places you have no chance to resist at all. What you can do, then, is find a new way out yourself."}),"\n",(0,o.jsx)(n.p,{children:"In a place where you have no voice and disclosure pays a negative return, the worst bargain is to stay entangled with it. Spending your strength proving you weren't wrong means staking whatever time you have left on a system that will never give you justice."}),"\n",(0,o.jsx)(n.p,{children:"Things in this world have their seasons. Unfair times pass, and fair times come again. No one knows how long the dark will last, and there may be darker times still. People in Hong Kong know this feeling well from recent years; many have at times felt there was no way out."}),"\n",(0,o.jsx)(n.p,{children:"But a way out has one simple property: only those who look for it find it. Look, and you may not find it; don't look, and you certainly won't. It's like the Mark Six lottery: hard to win, but only those who buy a ticket have any chance. Of course, life's odds are not as extreme as the lottery's."}),"\n",(0,o.jsxs)(n.p,{children:["I think of Ke Huy Quan. As a child he played major roles in ",(0,o.jsx)(n.em,{children:"Indiana Jones and the Temple of Doom"})," and ",(0,o.jsx)(n.em,{children:"The Goonies"}),", and he had a background in taekwondo. He was hardly lacking. But as he grew up, Hollywood had almost no roles for him, so he left the screen and worked behind the camera as a stunt choreographer and assistant director, often abroad (",(0,o.jsx)(n.a,{href:"https://www.nbcnews.com/news/asian-america/ke-huy-quan-love-hurts-lead-role-rcna191484",children:"NBC News"}),"). He did that for nearly twenty years."]}),"\n",(0,o.jsxs)(n.p,{children:["Then the tide turned. He won the Oscar for Best Supporting Actor for ",(0,o.jsx)(n.em,{children:"Everything Everywhere All at Once"}),". At 53, forty years into his career, he got his first leading film role. But ",(0,o.jsx)(n.em,{children:"Love Hurts"})," fared poorly with critics and audiences: it cost US$18 million and barely made its budget back worldwide (",(0,o.jsx)(n.a,{href:"https://www.the-numbers.com/movie/Love-Hurts-(2025)",children:"The Numbers"}),"). A turning tide does not mean smooth sailing from then on."]}),"\n",(0,o.jsx)(n.p,{children:"But he didn't sit and wait. Moving behind the camera was a path he found for himself, and when the chance came back, he was still in the game. Even if the leading-man road has been rough, he still has work."}),"\n",(0,o.jsx)(n.p,{children:"Yat Dang found his way out the same way. Around 2015 he wrote fewer TV dramas and moved to films, where contracts were more complete. He was never cheated again, kept his credits, and earned several times more. When the industry went into winter, he left Beijing."}),"\n",(0,o.jsx)(n.p,{children:"So Ah Ching started a new channel, from zero subscribers. That isn't giving up. He simply stopped leaving himself in a place that had already ruled against him."}),"\n",(0,o.jsx)(n.p,{children:"Even an unfair world has some fair corners, or at least places where you can survive. Those places won't come looking for you, and those who sit and wait rarely find them. I know this sounds a little like self-consolation. But at least those who look for a way out are the ones with a chance to leave."}),"\n",(0,o.jsx)(n.h2,{id:"sources",children:"Sources"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsx)(n.li,{children:"One Light Cinema (\u4e00\u71c8\u5f71\u8a71), \u3008\u89aa\u751f\u4ed4\u8ddf\u4eba\u59d3\uff01\u6211\u5728\u5317\u4eac\u505a\u300c\u5e7d\u9748\u7de8\u5287\u300d\u5341\u5e74\uff1a\u6700\u6bd2\u5514\u4fc2\u5ee3\u96fb\u7e3d\u5c40\uff0c\u4fc2\u81ea\u5df1\u4eba\uff01\u3009 (\"My own child took another man's name: ten years as a ghost screenwriter in Beijing\"), YouTube, 21 November 2026, in Cantonese. All of Yat Dang's experiences in this essay are his own account."}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.a,{href:"https://www.hk01.com/%E9%9B%BB%E5%BD%B1/977102/%E8%A8%B1%E5%86%A0%E6%96%87%E9%BB%83%E5%AD%90%E8%8F%AF32%E5%B9%B4%E5%BE%8C%E5%86%8D%E5%BA%A6%E5%90%88%E4%BD%9C-%E5%85%A9%E4%BB%A3%E7%AC%91%E5%8C%A0%E5%90%88%E9%AB%94%E8%AA%93%E5%89%B5%E9%81%8E%E5%84%84%E7%A5%A8%E6%88%BF%E7%A5%9E%E8%A9%B1",children:"\u8a31\u51a0\u6587\u9ec3\u5b50\u83ef32\u5e74\u5f8c\u518d\u5ea6\u5408\u4f5c"})," (Michael Hui and Dayo Wong reunite after 32 years), HK01, in Chinese."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.a,{href:"https://www.nbcnews.com/news/asian-america/ke-huy-quan-love-hurts-lead-role-rcna191484",children:"In 'Love Hurts,' Ke Huy Quan finally gets his lead role"}),", NBC News."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.a,{href:"https://www.the-numbers.com/movie/Love-Hurts-(2025)",children:"Love Hurts (2025)"}),", The Numbers."]}),"\n"]})]})}function c(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},28453(e,n,t){t.d(n,{R:()=>s,x:()=>r});var o=t(96540);const a={},i=o.createContext(a);function s(e){const n=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),o.createElement(i.Provider,{value:n},e.children)}}}]);